{"command": "cd /problem && cat > src/gemm.cu << 'EOF'
#include "gemm.cuh"

#include <cuda_runtime.h>

// SGEMM kernel for C = A * B, NxN row-major single-precision matrices.
//
// Design for NVIDIA A40 (sm_80, Ampere):
//   - Register tiling: each thread computes an 8x8 micro-tile of C.
//   - Block tile: 128x128 (16x16 threads).
//   - Shared-memory tiling over k in steps of BK=8, with vectorized loads.
//   - Handles arbitrary N (non-multiples of the tile) via bounds-checked loads.
//
// Shared memory usage: As[BM][BK(+pad)], Bs[BK][BN(+pad)].
//
//   BM = BN = 128, BK = 8.
//   As: 128*9 = 1152 floats ; Bs: 8*129 = 1032 floats ; total ~ 2184 floats
//       ~ 8.7 KB per block -> high occupancy.

#define BM 128
#define BN 128
#define BK 8
#define TM 8
#define TN 8

// Threads per block: (BM/TM) x (BN/TN) = 16 x 16 = 256
#define THREADS 256
#define TX 16
#define TY 16

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[BM][BK + 1];   // +1 padding to avoid bank conflicts
    __shared__ float Bs[BK][BN + 1];   // +1 padding

    const int tx = threadIdx.x;        // 0..15  (col within block)
    const int ty = threadIdx.y;        // 0..15  (row within block)

    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;

    const int numK = (N + BK - 1) / BK;

    // Global output indices for this thread's micro-tile.
    // Each thread handles rows [ty*TM .. ty*TM+TM-1] and cols [tx*TN .. tx*TN+TN-1]
    // within the block tile.

    // Accumulator registers (8x8)
    float rC[TM][TN];
#pragma unroll
    for (int i = 0; i < TM; ++i)
#pragma unroll
        for (int j = 0; j < TN; ++j)
            rC[i][j] = 0.0f;

