#define BN 128
#define BK 8
#define TM 8
#define TN 8

// Threads per block: (BM/TM) x (BN/TN) = 16 x 16 = 256
#define THREADS 256
#define TX 16
#define TY 16

__global__ void gemmKernel(const float* __restrict__ A,
                           const float* __restrict__ B,
                           float* __restrict__ C,
                           int N) {
    __shared__ float As[BM][BK + 1];   // +1 padding to avoid bank conflicts
    __shared__ float Bs[BK][BN + 1];   // +1 padding

    const int tx = threadIdx.x;        // 0..15  (col within block)
    const int ty = threadIdx.y;        // 0..15  (row within block)

    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;

    const int numK = (N + BK - 1) / BK;

    // Global output indices for this thread's micro-tile.
    // Each thread handles rows [ty*TM .. ty*TM+TM-1] and cols [tx*TN .. tx*TN+TN-1]
    // within the block tile.

    // Accumulator registers (8x8)
    float rC[TM][TN];
#pragma unroll
    for (int i = 0; i < TM; ++i)
#pragma unroll
        for (int j = 0; j < TN; ++j)
            rC[i][j] = 0.0f;

    for (int k0 = 0; k0 < numK; ++k0) {
        const int kGlobal = k0 * BK;

        // ---- Load As[BM][BK] and Bs[BK][BN] into shared, coalesced ----
        // Each block tile loads:
        //   As: rows [blockRow, blockRow+BM), cols [kGlobal, kGlobal+BK)
        //   Bs: rows [kGlobal, kGlobal+BK), cols [blockCol, blockCol+BN)
        // 256 threads; As has BM*BK = 1024 els; Bs has BK*BN = 1024 els;
        // each thread loads 4 elements (1 float4) per tile using vectorized loads.

        // As load: 1024 elements. Thread t handles elements [t*4, t*4+4).
