                if (gRow < N && gCol < N)
                    v = A[gRow * N + gCol];
                // store into As[r][c] (padded row width BK+1)
                As[r][c] = v;
            }
        }

        // Bs load: 1024 elements, rows [kGlobal..kGlobal+BK), cols blockCol+[0..BN)
        {
            const int idx = tx + ty * TX;
#pragma unroll
            for (int e = 0; e < 4; ++e) {
                const int lin = idx * 4 + e;
                const int r = lin / BN;           // row within B tile = k offset
                const int c = lin % BN;           // col within B tile
