    const int outRow0 = blockRow + ty * TM;
    const int outCol0 = blockCol + tx * TN;
#pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int r = outRow0 + i;
        if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < TN; ++j) {
