#include "src/gemm.cuh"
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>

#define CK(c) do { cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);} } while(0)

int main(){
    int N=2048;
    size_t bytes=(size_t)N*N*sizeof(float);
    std::vector<float> hA(N*N),hB(N*N),hC(N*N);
    std::mt19937 rng(42);
    std::uniform_real_distribution<float> d(-1,1);
    for(auto&x:hA)x=d(rng); for(auto&x:hB)x=d(rng);
    float *dA,*dB,*dC;
    CK(cudaMalloc(&dA,bytes)); CK(cudaMalloc(&dB,bytes)); CK(cudaMalloc(&dC,bytes));
    cudaMemcpy(dA,hA.data(),bytes,cudaMemcpyHostToDevice);
    cudaMemcpy(dB,hB.data(),bytes,cudaMemcpyHostToDevice);
    cudaMemset(dC,0,bytes);

    cublasHandle_t h; cublasCreate(&h);
    float alpha=1.0f,beta=0.0f;

    // warmup
    cudaEvent_t a,b; cudaEventCreate(&a); cudaEventCreate(&b);
    for(int i=0;i<5;i++){launchGemm(dA,dB,dC,N);}
    CK(cudaDeviceSynchronize());
    double mine=0;
    int iters=100;
    cudaEventRecord(a);
    for(int i=0;i<iters;i++) launchGemm(dA,dB,dC,N);
    cudaEventRecord(b); cudaEventSynchronize(b);
    float ms; cudaEventElapsedTime(&ms,a,b);
    mine=2.0*(double)N*N*N*iters/ (ms/1000.0)/1e9;

    // cublas
    for(int i=0;i<5;i++)cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC,N);
    CK(cudaDeviceSynchronize());
    cudaEventRecord(a);
    for(int i=0;i<iters;i++) cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dC,N);
    cudaEventRecord(b); cudaEventSynchronize(b);
    cudaEventElapsedTime(&ms,a,b);
    double cb=2.0*(double)N*N*N*iters/(ms/1000.0)/1e9;
    printf("mine   : %.1f GFLOP/s\n", mine);
    printf("cublas : %.1f GFLOP/s\n", cb);
    printf("ratio  : %.3f\n", mine/cb);
    return 0;
}
