    for (int i = 0; i < GTM; ++i)
#pragma unroll
        for (int j = 0; j < GTN; ++j)
            rC[i][j] = 0.0f;

    const int tid = tx + ty * 8;  // threads 8x8 = 64

    for (int k0 = 0; k0 < numK; ++k0) {
        const int kGlobal = k0 * GBK;
        // As load: GB*GBK = 32*16=512 elements /64 threads = 8 each
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            const int lin = tid * 8 + e;
            const int r = lin / GBK;
            const int c = lin % GBK;
            const int gRow = blockRow + r;
            const int gCol = kGlobal + c;
            As[r][c] = (gRow < N && gCol < N) ? A[(size_t)gRow * N + gCol] : 0.0f;
        }
        // Bs load: GBK*GB = 16*32=512/64=8 each
#pragma unroll
        for (int e = 0; e < 8; ++e) {
