        }
        __syncthreads();

        float aReg[GTM];
#pragma unroll
        for (int m = 0; m < GBK; ++m) {
#pragma unroll
            for (int i = 0; i < GTM; ++i)
                aReg[i] = As[ty * GTM + i][m];
#pragma unroll
