#include "gemm.cuh"

#include <cuda_runtime.h>

// ===========================================================================
//  Fast SGEMM kernel for C = A * B, NxN row-major single-precision matrices.
//
//  Design for NVIDIA A40 (sm_80, Ampere), tuned empirically on this GPU:
//    - Register tiling: each thread computes an 8x8 micro-tile of C.
//    - Block tile: BM x BN = 64 x 64 output, 8x8 = 64 threads.
//    - Shared-memory tiling over k in steps of BK=16.
//    - Double-buffered (2-stage) prefetch using cp.async (Ampere async copies)
//      to hide global-load latency.
//    - float4 vectorized global loads (requires N % 4 == 0).
//
//  This kernel is used when N % 4 == 0 (16-byte aligned rows); a generic,
//  fully-correct kernel (below) handles all other sizes.
// ===========================================================================

#define BM 64
#define BN 64
#define BK 16
#define TM 8
#define TN 8
#define TX 8
#define TY 8

// cp.async intrinsic for a 16-byte (float4) copy.
__device__ __forceinline__ void cp_async16(void* smem, const void* gmem) {
    unsigned smem_int = (unsigned)__cvta_generic_to_shared(smem);
    asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n" ::"r"(smem_int),
                 "l"(gmem));
}
__device__ __forceinline__ void cp_async_commit() {
    asm volatile("cp.async.commit_group;\n");
}
template <int N>
__device__ __forceinline__ void cp_async_wait() {
    asm volatile("cp.async.wait_group %0;\n" ::"n"(N));
}

// ---------------------------------------------------------------------------
// Fast path: N % 4 == 0. Double-buffered cp.async SGEMM.
// ---------------------------------------------------------------------------
__global__ void gemmKernelFast(const float* __restrict__ A,
                               const float* __restrict__ B,
                               float* __restrict__ C, int N) {
    __shared__ float As[2][BM][BK + 4];
    __shared__ float Bs[2][BK][BN + 4];

    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int blockRow = blockIdx.y * BM;
    const int blockCol = blockIdx.x * BN;
    const int numK = N / BK;

    const int outRow0 = blockRow + ty * TM;
    const int outCol0 = blockCol + tx * TN;

    float rC[TM][TN];
#pragma unroll
    for (int i = 0; i < TM; ++i)
#pragma unroll
        for (int j = 0; j < TN; ++j)
            rC[i][j] = 0.0f;

    const int tid = tx + ty * TX;
    const int af4perrow = BK / 4;   // float4s per A row
    const int bf4perrow = BN / 4;   // float4s per B row

    auto loadStage = [&](int stage, int k0) {
        // A: BM rows x BK cols
        {
            int f4a = tid;
            int row = f4a / af4perrow;
            int chunk = f4a % af4perrow;
            const float4* src = reinterpret_cast<const float4*>(
                A + (size_t)(blockRow + row) * N + k0 + chunk * 4);
            float4* dst = reinterpret_cast<float4*>(&As[stage][row][chunk * 4]);
            cp_async16(dst, src);
        }
        // B: BK rows x BN cols
        {
            int f4b = tid;
            int row = f4b / bf4perrow;
            int chunk = f4b % bf4perrow;
            const float4* src = reinterpret_cast<const float4*>(
                B + (size_t)(k0 + row) * N + blockCol + chunk * 4);
            float4* dst = reinterpret_cast<float4*>(&Bs[stage][row][chunk * 4]);
            cp_async16(dst, src);
        }
    };

    // Prologue: load stage 0
    loadStage(0, 0);
    cp_async_commit();

    for (int k = 0; k < numK; ++k) {
        const int cur = k & 1;
        const int nxt = (k + 1) & 1;
        if (k + 1 < numK) {
            loadStage(nxt, (k + 1) * BK);
            cp_async_commit();
        }
        cp_async_wait<1>();
        __syncthreads();

        float aReg[TM];
#pragma unroll
        for (int m = 0; m < BK; ++m) {
#pragma unroll
            for (int i = 0; i < TM; ++i)
                aReg[i] = As[cur][ty * TM + i][m];
#pragma unroll
            for (int j = 0; j < TN; ++j) {
                const float b = Bs[cur][m][tx * TN + j];
#pragma unroll
                for (int i = 0; i < TM; ++i)
                    rC[i][j] += aReg[i] * b;
            }
        }
        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int r = outRow0 + i;
        if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int c = outCol0 + j;
            if (c < N) C[(size_t)r * N + c] = rC[i][j];
        }
    }
}

// ---------------------------------------------------------------------------
// Generic correct kernel for arbitrary N (used when N % 4 != 0, e.g. N=257).
// Bounds-checked scalar loads.
// ---------------------------------------------------------------------------
#define GB 32
#define GBK 16
#define GTM 4
#define GTN 4

__global__ void gemmKernelGeneric(const float* __restrict__ A,
                                  const float* __restrict__ B,
                                  float* __restrict__ C, int N) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int blockRow = blockIdx.y * GB;
    const int blockCol = blockIdx.x * GB;
    const int numK = (N + GBK - 1) / GBK;

    __shared__ float As[GB][GBK + 1];
    __shared__ float Bs[GBK][GB + 1];

    float rC[GTM][GTN];
#pragma unroll
    for (int i = 0; i < GTM; ++i)
#pragma unroll
        for (int j = 0; j < GTN; ++j)
            rC[i][j] = 0.0f;

    const int tid = tx + ty * 8;

    for (int k0 = 0; k0 < numK; ++k0) {
        const int kGlobal = k0 * GBK;
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            const int lin = tid * 8 + e;
            const int r = lin / GBK;
            const int c = lin % GBK;
            const int gRow = blockRow + r;
            const int gCol = kGlobal + c;
            As[r][c] = (gRow < N && gCol < N) ? A[(size_t)gRow * N + gCol] : 0.0f;
        }
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            const int lin = tid * 8 + e;
            const int r = lin / GB;
            const int c = lin % GB;
            const int gRow = kGlobal + r;
            const int gCol = blockCol + c;
            Bs[r][c] = (gRow < N && gCol < N) ? B[(size_t)gRow * N + gCol] : 0.0f;
        }
        __syncthreads();

        float aReg[GTM];
#pragma unroll
        for (int m = 0; m < GBK; ++m) {
#pragma unroll
            for (int i = 0; i < GTM; ++i)
                aReg[i] = As[ty * GTM + i][m];
#pragma unroll
            for (int j = 0; j < GTN; ++j) {
                const float b = Bs[m][tx * GTN + j];
#pragma unroll
                for (int i = 0; i < GTM; ++i)
                    rC[i][j] += aReg[i] * b;
            }
        }
        __syncthreads();
    }

    const int outRow0 = blockRow + ty * GTM;
    const int outCol0 = blockCol + tx * GTN;
#pragma unroll
    for (int i = 0; i < GTM; ++i) {
        const int r = outRow0 + i;
        if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < GTN; ++j) {
            const int c = outCol0 + j;
            if (c < N) C[(size_t)r * N + c] = rC[i][j];
        }
    }
}

void launchGemm(const float* dA, const float* dB, float* dC, int N) {
    if (N % 4 == 0) {
        dim3 block(TX, TY);
        dim3 grid((N + BN - 1) / BN, (N + BM - 1) / BM);
        gemmKernelFast<<<grid, block>>>(dA, dB, dC, N);
    } else {
        dim3 block(8, 8);
        dim3 grid((N + GB - 1) / GB, (N + GB - 1) / GB);
        gemmKernelGeneric<<<grid, block>>>(dA, dB, dC, N);
    }
}
