#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <cstring>
#define CK(c) do { cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);} } while(0)
__device__ __forceinline__ void cpa(void* s,const void* g){unsigned si=(unsigned)__cvta_generic_to_shared(s);asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"::"r"(si),"l"(g));}
__device__ __forceinline__ void cpcomm(){asm volatile("cp.async.commit_group;\n");}
template<int N>__device__ __forceinline__ void cpwait(){asm volatile("cp.async.wait_group %0;\n"::"n"(N));}

// PAD_A, PAD_B options; SWIZZLE option for B
template<int APAD,int BPAD,bool SWIZ>
__global__ void __launch_bounds__(64) kfast(const float* __restrict__ A,const float* __restrict__ B,float* __restrict__ C,int N){
    const int BM=64,BN=64,BK=16,TM=8,TN=8,TX=8,TY=8;
    __shared__ float As[2][BM][BK+APAD];
    __shared__ float Bs[2][BK][BN+BPAD];
    const int tx=threadIdx.x, ty=threadIdx.y;
    const int blockRow=blockIdx.y*BM, blockCol=blockIdx.x*BN;
    const int numK=N/BK;
    const int outRow0=blockRow+ty*TM, outCol0=blockCol+tx*TN;
    float rC[TM][TN];
#pragma unroll
    for(int i=0;i<TM;++i)
#pragma unroll
        for(int j=0;j<TN;++j) rC[i][j]=0.0f;
    const int tid=tx+ty*TX;
    const int af4perrow=BK/4, bf4perrow=BN/4;
    auto loadStage=[&](int stage,int k0){
        for(int e=0;e<4;++e){int f4a=tid+e*64;int row=f4a/af4perrow;int chunk=f4a%af4perrow;
            const float4* src=reinterpret_cast<const float4*>(A+(size_t)(blockRow+row)*N+k0+chunk*4);
            float4* dst=reinterpret_cast<float4*>(&As[stage][row][chunk*4]);cpa(dst,src);}
        for(int e=0;e<4;++e){int f4b=tid+e*64;int row=f4b/bf4perrow;int chunk=f4b%bf4perrow;
            const float4* src=reinterpret_cast<const float4*>(B+(size_t)(k0+row)*N+blockCol+chunk*4);
            float4* dst=reinterpret_cast<float4*>(&Bs[stage][row][chunk*4]);cpa(dst,src);}
    };
    loadStage(0,0);cpcomm();
    for(int k=0;k<numK;++k){
        const int cur=k&1,nxt=(k+1)&1;
        if(k+1<numK){loadStage(nxt,(k+1)*BK);cpcomm();}
        cpwait<1>();__syncthreads();
        float aReg[TM];
#pragma unroll
        for(int m=0;m<BK;++m){
#pragma unroll
            for(int i=0;i<TM;++i) aReg[i]=As[cur][ty*TM+i][m];
#pragma unroll
            for(int j=0;j<TN;++j){
                float b;
                if(SWIZ){ // swizzle: xor col with (m&3)<<3
                    int col=tx*TN+j;
                    int sw=col ^ ((m&3)<<3);
                    b=Bs[cur][m][sw];
                } else b=Bs[cur][m][tx*TN+j];
#pragma unroll
                for(int i=0;i<TM;++i) rC[i][j]+=aReg[i]*b;
            }
        }
        __syncthreads();
    }
#pragma unroll
    for(int i=0;i<TM;++i){const int r=outRow0+i;if(r>=N)continue;
#pragma unroll
        for(int j=0;j<TN;++j){const int c=outCol0+j;if(c<N)C[(size_t)r*N+c]=rC[i][j];}}
}

template<int APAD,int BPAD,bool SWIZ>
void lrun(const char* n,int N,int iters){
    size_t bytes=(size_t)N*N*sizeof(float);
    float*dA,*dB,*dC;CK(cudaMalloc(&dA,bytes));CK(cudaMalloc(&dB,bytes));CK(cudaMalloc(&dC,bytes));cudaMemset(dC,0,bytes);
    cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
    dim3 blk(8,8),grd((N+63)/64,(N+63)/64);
    for(int i=0;i<10;i++)kfast<APAD,BPAD,SWIZ><<<grd,blk>>>(dA,dB,dC,N);
    CK(cudaDeviceSynchronize());
    cudaEventRecord(a);
    for(int i=0;i<iters;i++)kfast<APAD,BPAD,SWIZ><<<grd,blk>>>(dA,dB,dC,N);
    cudaEventRecord(b);cudaEventSynchronize(b);
    float ms;cudaEventElapsedTime(&ms,a,b);
    double gf=2.0*(double)N*N*N*iters/(ms/1000.0)/1e9;
    printf("%-22s : %.0f GFLOP/s\n",n,gf);
    cudaFree(dA);cudaFree(dB);cudaFree(dC);
}

int main(){
    int N=2048,it=200;
    lrun<4,4,false>("pad4x4",N,it);
    lrun<0,0,false>("pad0x0",N,it);
    lrun<0,4,false>("pad0x4",N,it);
    lrun<4,0,false>("pad4x0",N,it);
    lrun<4,4,true>("pad4x4-swiz",N,it);
    lrun<0,68,false>("padB68",N,it);
    return 0;
}
