template<int BM,int BN,int BK,int TM,int TN,int TC,int APAD,int BPAD>
__global__ void __launch_bounds__(BM*BN/(TM*TN)) kf(const float*__restrict__ A,const float*__restrict__ B,float*__restrict__ C,int N){
    __shared__ float As[2][BM][BK+APAD];
    __shared__ float Bs[2][BK][BN+BPAD];
    const int tx=threadIdx.x,ty=threadIdx.y;
    const int blockRow=blockIdx.y*BM,blockCol=blockIdx.x*BN;
    const int numK=N/BK;
    const int nthreads=BM*BN/(TM*TN);
    const int tid=tx+ty*TC;
    float rC[TM][TN];
#pragma unroll
    for(int i=0;i<TM;++i)
#pragma unroll
        for(int j=0;j<TN;++j)rC[i][j]=0;
    const int af4perrow=BK/4,bf4perrow=BN/4;
    const int af4total=BM*BK/4,bf4total=BK*BN/4;
    auto loadStage=[&](int stage,int k0){
        #pragma unroll
        for(int f4a=tid;f4a<af4total;f4a+=nthreads){int row=f4a/af4perrow;int chunk=f4a%af4perrow;
            cpa(&As[stage][row][chunk*4],(const float4*)(A+(size_t)(blockRow+row)*N+k0+chunk*4));}
        #pragma unroll
        for(int f4b=tid;f4b<bf4total;f4b+=nthreads){int row=f4b/bf4perrow;int chunk=f4b%bf4perrow;
            cpa(&Bs[stage][row][chunk*4],(const float4*)(B+(size_t)(k0+row)*N+blockCol+chunk*4));}
    };
    loadStage(0,0);cpcomm();
    for(int k=0;k<numK;++k){
        const int cur=k&1,nxt=(k+1)&1;
        if(k+1<numK){loadStage(nxt,(k+1)*BK);cpcomm();}
        cpwait<1>();__syncthreads();
#pragma unroll
        for(int m=0;m<BK;++m){
            float aReg[TM];
#pragma unroll
            for(int i=0;i<TM;++i) aReg[i]=As[cur][ty*TM+i][m];
#pragma unroll
            for(int j=0;j<TN;++j){
                const float b=Bs[cur][m][tx*TN+j];
#pragma unroll
                for(int i=0;i<TM;++i) rC[i][j]+=aReg[i]*b;
            }
        }
        __syncthreads();
    }
#pragma unroll
    for(int i=0;i<TM;++i){int r=blockRow+ty*TM+i;if(r>=N)continue;
#pragma unroll
        for(int j=0;j<TN;++j){int c=blockCol+tx*TN+j;if(c<N)C[(size_t)r*N+c]=rC[i][j];}}
}
