template<int BM,int BN,int BK,int TM,int TN,int TC,int APAD,int BPAD>
double gfmin(float*dA,float*dB,float*dC,int N,int reps){
    cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
    runK<BM,BN,BK,TM,TN,TC,APAD,BPAD>(dA,dB,dC,N);cudaDeviceSynchronize();
    double best=1e18;
    for(int r=0;r<reps;r++){cudaEventRecord(a);runK<BM,BN,BK,TM,TN,TC,APAD,BPAD>(dA,dB,dC,N);cudaEventRecord(b);cudaEventSynchronize(b);
        float ms;cudaEventElapsedTime(&ms,a,b);double g=2.0*(double)N*N*N/(ms/1000.0)/1e9;if(g<best)best=g;}
    return best;
}
double gfblas(float*dA,float*dB,float*dC,int N,int reps){
