    double best=1e18;
    for(int r=0;r<reps;r++){cudaEventRecord(a);cublasSgemm(gh,CUBLAS_OP_N,CUBLAS_OP_N,gN,gN,gN,&ga,gdA,gN,gdB,gN,&gbb,gdC,gN);cudaEventRecord(b);cudaEventSynchronize(b);
        float ms;cudaEventElapsedTime(&ms,a,b);double g=2.0*(double)N*N*N/(ms/1000.0)/1e9;if(g<best)best=g;}
