        runK<64,128,16,16,4,32,4,4>(dA,dB,dC,N);
        runK<128,64,16,16,4,16,4,4>(dA,dB,dC,N);
        cublasSgemm(gh,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&ga,dA,N,dB,N,&gbb,dC,N);
    }
    cudaDeviceSynchronize();
    double acc[4]={0};const char*names[4]={"64x64 pad4","64x64 pad0x4","64x128","128x64"};
    int R=8;
