        double b=gfblas(dA,dB,dC,N,reps);
        double g[4]={
            gfmin<64,64,16,16,4,16,4,4>(dA,dB,dC,N,reps),
            gfmin<64,64,16,16,4,16,0,4>(dA,dB,dC,N,reps),
            gfmin<64,128,16,16,4,32,4,4>(dA,dB,dC,N,reps),
            gfmin<128,64,16,16,4,16,4,4>(dA,dB,dC,N,reps)};
        for(int i=0;i<4;i++)acc[i]+=g[i]/b/R;
    }
    for(int i=0;i<4;i++)printf("%-12s ratio=%.3f\n",names[i],acc[i]);
    return 0;
}
