#include "src/gemm.cuh"
#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>
#define CK(c) do { cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);} } while(0)
int main(){
    int Ns[]={16,32,64,100,128,200,256,257,300,384,511,512,1000,1024,2048,3072,4096,5000,8192};
    cublasHandle_t h; cublasCreate(&h);
    for(int n=0;n<19;n++){
        int N=Ns[n]; size_t bytes=(size_t)N*N*sizeof(float);
        std::vector<float> hA(N*N),hB(N*N),hC(N*N),hR(N*N);
        std::mt19937 rng(5);std::uniform_real_distribution<float>d(-1,1);
        for(auto&x:hA)x=d(rng);for(auto&x:hB)x=d(rng);
        float *dA,*dB,*dC,*dR;CK(cudaMalloc(&dA,bytes));CK(cudaMalloc(&dB,bytes));CK(cudaMalloc(&dC,bytes));CK(cudaMalloc(&dR,bytes));
        cudaMemcpy(dA,hA.data(),bytes,cudaMemcpyHostToDevice);cudaMemcpy(dB,hB.data(),bytes,cudaMemcpyHostToDevice);
        cudaMemset(dC,0,bytes);cudaMemset(dR,0,bytes);
        launchGemm(dA,dB,dC,N);CK(cudaDeviceSynchronize());
        float alpha=1,beta=0;
        cublasSgemm(h,CUBLAS_OP_N,CUBLAS_OP_N,N,N,N,&alpha,dA,N,dB,N,&beta,dR,N);
        CK(cudaDeviceSynchronize());
        cudaMemcpy(hC.data(),dC,bytes,cudaMemcpyDeviceToHost);cudaMemcpy(hR.data(),dR,bytes,cudaMemcpyDeviceToHost);
        double s=0;for(size_t i=0;i<(size_t)N*N;i++){double dd=(double)hC[i]-(double)hR[i];s+=dd*dd;}
        double mse=s/((size_t)N*N);
        printf("N=%-4d MSE=%.3e %s\n",N,mse,mse<1e-5?"ok":"FAIL");
        cudaFree(dA);cudaFree(dB);cudaFree(dC);cudaFree(dR);
    }
    return 0;
}
