#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>
#define CK(c) do { cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);} } while(0)
__global__ void serial(const float*A,const float*B,float*C,int N){
    int idx=blockIdx.x*blockDim.x+threadIdx.x;if(idx>=N*N)return;int r=idx/N,c=idx%N;double acc=0;
    for(int k=0;k<N;k++)acc+=(double)A[r*N+k]*(double)B[k*N+c];C[idx]=(float)acc;
}
// copy of generic kernel proto
#include "src/gemm.cuh"
extern __global__ void gemmKernelGeneric(const float*,const float*,float*,int);
int main(){
    int N=16;size_t bytes=(size_t)N*N*sizeof(float);
    std::vector<float>hA(N*N),hB(N*N),hC(N*N),hR(N*N);
    std::mt19937 rng(5);std::uniform_real_distribution<float>d(-1,1);
    for(auto&x:hA)x=d(rng);for(auto&x:hB)x=d(rng);
    float*dA,*dB,*dC,*dR;CK(cudaMalloc(&dA,bytes));CK(cudaMalloc(&dB,bytes));CK(cudaMalloc(&dC,bytes));CK(cudaMalloc(&dR,bytes));
    cudaMemcpy(dA,hA.data(),bytes,cudaMemcpyHostToDevice);cudaMemcpy(dB,hB.data(),bytes,cudaMemcpyHostToDevice);
    gemmKernelGeneric<<<dim3((N+31)/32,(N+31)/32),dim3(8,8)>>>(dA,dB,dC,N);
    serial<<<(N*N+255)/256,256>>>(dA,dB,dR,N);
    cudaDeviceSynchronize();
    cudaMemcpy(hC.data(),dC,bytes,cudaMemcpyDeviceToHost);cudaMemcpy(hR.data(),dR,bytes,cudaMemcpyDeviceToHost);
    double s=0;for(int i=0;i<N*N;i++){double dd=(double)hC[i]-(double)hR[i];s+=dd*dd;}
    printf("generic N=16 MSE=%.3e\n",s/((size_t)N*N));
    return 0;
}
