#include <cuda_runtime.h>
#include <cublas_v2.h>
#include <cstdio>
#include <cstdlib>
#define CK(c) do { cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);} } while(0)
// launcher functions via the actual gemm kernel (t16x4) and a fresh t8x8
// We'll compare both by calling cublas and two kernel variants.
// Import the gemm kernel from gemm.cu indirectly: we re-implement a t8x8 wrapper.
__device__ __forceinline__ void cpa(void* s,const void* g){unsigned si=(unsigned)__cvta_generic_to_shared(s);asm volatile("cp.async.cg.shared.global [%0], [%1], 16;\n"::"r"(si),"l"(g));}
__device__ __forceinline__ void cpcomm(){asm volatile("cp.async.commit_group;\n");}
template<int N>__device__ __forceinline__ void cpwait(){asm volatile("cp.async.wait_group %0;\n"::"n"(N));}
// t8x8
__global__ void __launch_bounds__(64) k88(const float*__restrict__ A,const float*__restrict__ B,float*__restrict__ C,int N){
    const int BK=16,BM=64,BN=64;
    __shared__ float As[2][BM][BK+4];__shared__ float Bs[2][BK][BN+4];
    const int tx=threadIdx.x,ty=threadIdx.y;
    const int blockRow=blockIdx.y*BM,blockCol=blockIdx.x*BN;const int numK=N/BK;
    float rC[8][8];
#pragma unroll
    for(int i=0;i<8;++i)
#pragma unroll
        for(int j=0;j<8;++j)rC[i][j]=0;
    const int tid=tx+ty*8;
    auto loadStage=[&](int st,int k0){
        for(int e=0;e<4;++e){int f4a=tid+e*64;int row=f4a/4;int ch=f4a%4;cpa(&As[st][row][ch*4],(const float4*)(A+(size_t)(blockRow+row)*N+k0+ch*4));}
        for(int e=0;e<4;++e){int f4b=tid+e*64;int row=f4b/16;int ch=f4b%16;cpa(&Bs[st][row][ch*4],(const float4*)(B+(size_t)(k0+row)*N+blockCol+ch*4));}
    };
    loadStage(0,0);cpcomm();
    for(int k=0;k<numK;++k){int cur=k&1,nxt=(k+1)&1;
        if(k+1<numK){loadStage(nxt,(k+1)*BK);cpcomm();}
        cpwait<1>();__syncthreads();
#pragma unroll
        for(int m=0;m<BK;++m){float aReg[8];
#pragma unroll
            for(int i=0;i<8;++i)aReg[i]=As[cur][ty*8+i][m];
#pragma unroll
            for(int j=0;j<8;++j){float b=Bs[cur][m][tx*8+j];
#pragma unroll
                for(int i=0;i<8;++i)rC[i][j]+=aReg[i]*b;}}
        __syncthreads();
    }
#pragma unroll
    for(int i=0;i<8;++i){int r=blockRow+ty*8+i;if(r>=N)continue;
#pragma unroll
        for(int j=0;j<8;++j){int c=blockCol+tx*8+j;if(c<N)C[(size_t)r*N+c]=rC[i][j];}}
}
void run88(float*A,float*B,float*C,int N){k88<<<dim3((N+63)/64,(N+63)/64),dim3(8,8)>>>(A,B,C,N);}
// t16x4 uses gemm.cu's gemmKernelFast via extern
extern __global__ void gemmKernelFast(const float*,const float*,float*,int);
void run164(float*A,float*B,float*C,int N){gemmKernelFast<<<dim3((N+63)/64,(N+63)/64),dim3(16,4)>>>(A,B,C,N);}
cublasHandle_t gh;int gN;float ga=1,gbb=0;float*gdA,*gdB,*gdC;
void runBlas(float*,float*,float*,int){cublasSgemm(gh,CUBLAS_OP_N,CUBLAS_OP_N,gN,gN,gN,&ga,gdA,gN,gdB,gN,&gbb,gdC,gN);}
double gfmin(void(*fn)(float*,float*,float*,int),int N,int reps){
    cudaEvent_t a,b;cudaEventCreate(&a);cudaEventCreate(&b);
    fn(gdA,gdB,gdC,N);cudaDeviceSynchronize();
    double best=1e18;
    for(int r=0;r<reps;r++){cudaEventRecord(a);fn(gdA,gdB,gdC,N);cudaEventRecord(b);cudaEventSynchronize(b);
        float ms;cudaEventElapsedTime(&ms,a,b);double g=2.0*(double)N*N*N/(ms/1000.0)/1e9;if(g<best)best=g;}
    return best;
}
int main(){
    int N=2048;size_t bytes=(size_t)N*N*sizeof(float);
    CK(cudaMalloc(&gdA,bytes));CK(cudaMalloc(&gdB,bytes));CK(cudaMalloc(&gdC,bytes));
    cudaMemset(gdC,0,bytes);cublasCreate(&gh);gN=N;
    int reps=30;
    for(int i=0;i<50;i++){runBlas(gdA,gdB,gdC,N);run88(gdA,gdB,gdC,N);run164(gdA,gdB,gdC,N);}
    cudaDeviceSynchronize();
    for(int it=0;it<4;it++){
        double b=gfmin(runBlas,N,reps);
        double g88=gfmin(run88,N,reps);
        double g164=gfmin(run164,N,reps);
        printf("blas=%.0f  t8x8=%.0f(%.3f)  t16x4=%.0f(%.3f)\n",b,g88,g88/b,g164,g164/b);
    }
    return 0;
}
