    loadStage(0, 0);
    cp_async_commit();

    for (int k = 0; k < numK; ++k) {
        const int cur = k & 1;
        const int nxt = (k + 1) & 1;
        if (k + 1 < numK) {
            loadStage(nxt, (k + 1) * BK);
            cp_async_commit();
        }
