        __syncthreads();

        // Register-blocked FMA: load the B fragments needed by this thread,
        // then issue A*B FMAs. We process two k values per iteration (m-pair
        // unrolling) to give the compiler more independent FMAs to overlap the
        // shared-memory load latency.
#pragma unroll
        for (int m = 0; m < BK; m += 2) {
            float bReg0[TN], bReg1[TN];
#pragma unroll
            for (int j = 0; j < TN; ++j) {
                bReg0[j] = Bs[cur][m][tx * TN + j];
                bReg1[j] = Bs[cur][m + 1][tx * TN + j];
            }
#pragma unroll
            for (int i = 0; i < TM; ++i) {
                const float a0 = As[cur][ty * TM + i][m];
                const float a1 = As[cur][ty * TM + i][m + 1];
#pragma unroll
                for (int j = 0; j < TN; ++j) {
                    rC[i][j] += a0 * bReg0[j];
                    rC[i][j] += a1 * bReg1[j];
                }
            }
        }
        __syncthreads();
    }

#pragma unroll
    for (int i = 0; i < TM; ++i) {
        const int r = outRow0 + i;
        if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < TN; ++j) {
            const int c = outCol0 + j;
            if (c < N) C[(size_t)r * N + c] = rC[i][j];
        }
    }
