// ---------------------------------------------------------------------------
// Generic correct kernel for arbitrary N (used when N % 16 != 0, e.g. N=200,257).
// Bounds-checked scalar loads.
// ---------------------------------------------------------------------------
#define GB 32
#define GBK 16
#define GTM 4
#define GTN 4

__global__ void gemmKernelGeneric(const float* __restrict__ A,
                                  const float* __restrict__ B,
                                  float* __restrict__ C, int N) {
    const int tx = threadIdx.x;
    const int ty = threadIdx.y;
    const int blockRow = blockIdx.y * GB;
    const int blockCol = blockIdx.x * GB;
    const int numK = (N + GBK - 1) / GBK;

    __shared__ float As[GB][GBK + 1];
    __shared__ float Bs[GBK][GB + 1];

    float rC[GTM][GTN];
#pragma unroll
    for (int i = 0; i < GTM; ++i)
#pragma unroll
        for (int j = 0; j < GTN; ++j)
            rC[i][j] = 0.0f;

    const int tid = tx + ty * 8;

    for (int k0 = 0; k0 < numK; ++k0) {
        const int kGlobal = k0 * GBK;
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            const int lin = tid * 8 + e;
            const int r = lin / GBK;
            const int c = lin % GBK;
            const int gRow = blockRow + r;
            const int gCol = kGlobal + c;
            As[r][c] = (gRow < N && gCol < N) ? A[(size_t)gRow * N + gCol] : 0.0f;
        }
#pragma unroll
        for (int e = 0; e < 8; ++e) {
            const int lin = tid * 8 + e;
            const int r = lin / GB;
            const int c = lin % GB;
            const int gRow = kGlobal + r;
            const int gCol = blockCol + c;
            Bs[r][c] = (gRow < N && gCol < N) ? B[(size_t)gRow * N + gCol] : 0.0f;
        }
        __syncthreads();

        float aReg[GTM];
#pragma unroll
        for (int m = 0; m < GBK; ++m) {
#pragma unroll
            for (int i = 0; i < GTM; ++i)
                aReg[i] = As[ty * GTM + i][m];
#pragma unroll
            for (int j = 0; j < GTN; ++j) {
                const float b = Bs[m][tx * GTN + j];
#pragma unroll
                for (int i = 0; i < GTM; ++i)
                    rC[i][j] += aReg[i] * b;
            }
        }
        __syncthreads();
    }

    const int outRow0 = blockRow + ty * GTM;
    const int outCol0 = blockCol + tx * GTN;
#pragma unroll
    for (int i = 0; i < GTM; ++i) {
        const int r = outRow0 + i;
        if (r >= N) continue;
#pragma unroll
        for (int j = 0; j < GTN; ++j) {
            const int c = outCol0 + j;
            if (c < N) C[(size_t)r * N + c] = rC[i][j];
        }
    }
