#include "src/gemm.cuh"
#include <cuda_runtime.h>
#include <cstdio>
#include <cstdlib>
#include <random>
#include <vector>
#define CK(c) do { cudaError_t e=(c); if(e!=cudaSuccess){fprintf(stderr,"CUDA %s\n",cudaGetErrorString(e));exit(1);} } while(0)
double msedb(int N){
    size_t bytes=(size_t)N*N*sizeof(float);
    std::vector<float>hA(N*N),hB(N*N),hC(N*N),hR(N*N);
    std::mt19937 rng(5);std::uniform_real_distribution<float>d(-1,1);
    for(auto&x:hA)x=d(rng);for(auto&x:hB)x=d(rng);
    for(int i=0;i<N;i++)for(int j=0;j<N;j++){double a=0;for(int k=0;k<N;k++)a+=(double)hA[i*N+k]*(double)hB[k*N+j];hR[i*N+j]=(float)a;}
    float*dA,*dB,*dC;CK(cudaMalloc(&dA,bytes));CK(cudaMalloc(&dB,bytes));CK(cudaMalloc(&dC,bytes));
    cudaMemcpy(dA,hA.data(),bytes,cudaMemcpyHostToDevice);cudaMemcpy(dB,hB.data(),bytes,cudaMemcpyHostToDevice);
    cudaMemset(dC,0,bytes);
    launchGemm(dA,dB,dC,N);CK(cudaDeviceSynchronize());
    cudaMemcpy(hC.data(),dC,bytes,cudaMemcpyDeviceToHost);
    double s=0;for(int i=0;i<N*N;i++){double dd=(double)hC[i]-(double)hR[i];s+=dd*dd;}
    return s/((size_t)N*N);
}
int main(){for(int N:{64,80,96,112,128,144,160,192,200,224,256,257,320,384,448,512,576,640,700,768,800,896,1000,1024,1280,1344,1500,1664,1792,1920,2048})printf("N=%-4d MSE=%.3e %s\n",N,msedb(N),msedb(N)<1e-5?"ok":"FAIL");return 0;}
EOF
